import{_t as e,it as t,n,ot as r,rt as i,xt as a}from"./chunks/framework.yS8CksER.js";var o=JSON.parse(`{"title":"Metamodell-Pakete","description":"","frontmatter":{"title":"Metamodell-Pakete","covers":{"screens":[],"stories":["US-033"]}},"headers":[],"relativePath":"de/administration/metamodel-packages.md","filePath":"de/administration/metamodel-packages.md"}`),s={name:`de/administration/metamodel-packages.md`};function c(n,o,s,c,l,u){let d=a(`Screenshot`);return e(),i(`div`,null,[o[0]||=t(`<h1 id="metamodell-pakete" tabindex="-1">Metamodell-Pakete <a class="header-anchor" href="#metamodell-pakete" aria-label="Permalink to “Metamodell-Pakete”">​</a></h1><p>Eine neue Instanz hat keine Entitätstypen. Bevor jemand Entitäten erfassen kann, importierst du ein Metamodell: das mitgelieferte Starterpaket oder ein eigenes Paket.</p><p>Der Import von Paketen verlangt die Berechtigung <code>metamodel:write</code>, die nur die Rolle <code>metamodel-admin</code> hat – nicht das lokale Systemadmin-Konto. Ordne eine IdP-Gruppe <code>metamodel-admin</code> zu (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>); als privilegierte Rolle braucht sie einen zweiten Faktor beim Identity-Provider.</p><h2 id="starterkonfiguration-importieren" tabindex="-1">Starterkonfiguration importieren <a class="header-anchor" href="#starterkonfiguration-importieren" aria-label="Permalink to “Starterkonfiguration importieren”">​</a></h2><p>OEA liefert das Starterpaket <code>oea-starter-togaf-classic</code> mit den Entitätstypen Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software und Network Node, jeweils mit der Eigenschaft <em>Status</em>.</p><p>Solange die Instanz keinen Entitätstyp hat, zeigt die Startseite einer Person mit <code>metamodel:write</code> den Bereich <em>Import starter configuration</em>. Wähle <em>Import</em> neben dem Paket; die Seite bestätigt, wie viele Entitätstypen jetzt verfügbar sind.</p>`,6),r(d,{name:`starter-import`,alt:`Startseite mit der Starterkonfiguration zum Import`}),o[1]||=t('<p>Über die API:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                          # Liste mit Zusammenfassung</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # importierte Entitätstypen</span></span></code></pre></div><h2 id="eigenes-paket-importieren" tabindex="-1">Eigenes Paket importieren <a class="header-anchor" href="#eigenes-paket-importieren" aria-label="Permalink to “Eigenes Paket importieren”">​</a></h2><p>Eigene Pakete verwenden dasselbe JSON-Format (<code>MetamodelPackage</code>, mit <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> und stabilen UUIDs pro Element). Importiere sie mit <code>POST /admin/metamodel/import</code>:</p><ul><li>Ein Paket wird vollständig oder gar nicht importiert. Importierte Inhalte bekommen den Scope <code>imported</code> und das Paket als Herkunft.</li><li>Ein erneuter Import desselben Pakets aktualisiert dessen eigene Inhalte. Inhalte eines anderen Pakets oder deiner Organisation werden nie überschrieben; die Antwort ist <code>409</code> mit der Liste der Konflikte.</li><li>Pakete, die größer als <code>oea.metamodel.import.max-size</code> sind (Standard 10 MB), werden mit <code>413</code> abgelehnt; fehlerhaftes JSON oder Inhalte, die nicht zum Format passen, mit <code>422</code> und der Stelle des Problems.</li><li>Die Strategie <code>replace</code>, Viewpoints, Shape-Zuordnungen und Übersetzungspakete werden noch nicht unterstützt (<code>422</code>).</li></ul><p>Jeder Import schreibt die Audit-Events <code>metamodel.package-imported</code> und <code>metamodel.metatype-imported</code> mit einer gemeinsamen Batch-ID.</p>',6)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};